import {budgetSummary,ESSENTIAL_KEYS,FLEXIBLE_KEYS,DEBT_KEYS,IMPORT_KEYS} from './budget.js';
import {GROUPS} from './model.js';
import {budgetAllocation,inputOrigin} from './presentation.js';

export function budgetView(state,{title,section,fields,help,miniNote,taxControls}){
 const origin=inputOrigin(state,'budget','currentHousing');
 return title('MONTHLY BUDGET','Your month, with room to breathe.','Planned spending and savings, shared with both home calculators.')+
 `<div class="budget-overview"><section class="panel budget-chart-panel"><div id="budget-chart"></div></section><aside id="results"></aside></div><div id="input-panels" class="budget-inputs">`+
 section('01','Income & paycheck deductions','Gross pay, retirement, and editable tax estimates',fields(['householdGrossAnnual','pre401k'])+(taxControls?taxControls():fields(['incomeTaxRate','payrollTaxRate']))+miniNote('Enter gross pay, not your bank deposit. Retirement is deducted once before take-home; health insurance is counted once under Essentials.'))+
 section('02','Current housing','Rent or ownership costs, including utilities',`<div class="fields"><div class="field"><div class="field-label"><label for="b-currentHousing">Current housing / month</label>${help('currentHousing')}</div><div class="input-wrap"><span>$</span><input class="${origin==='example'?'example-value':''}" id="b-currentHousing" type="number" data-budget="currentHousing" aria-describedby="origin-currentHousing" min="0" max="1000000000" step="any" value="${state.budget.currentHousing}"></div><small id="origin-currentHousing" class="entry-origin">${{example:'Example · editable',entered:'Your entry',saved:'Saved value',imported:'Imported entry'}[origin]}</small></div></div>`+miniNote('Include rent plus utilities, or your current mortgage, tax, insurance, HOA, utilities, and maintenance. Proposed ownership replaces this amount.'))+
 section('03','Everyday essentials','Food, transport, childcare, healthcare & protection',fields(ESSENTIAL_KEYS))+
 section('04','Flexible spending','Restaurants, shopping, travel, hobbies & giving',fields(FLEXIBLE_KEYS))+
 section('05','Debt payments','Payments each month, not remaining balances',fields(DEBT_KEYS)+miniNote('Credit-card purchases belong in spending categories. Put repayment of older card debt here; do not count this month’s purchases again as a card payment.'))+
 section('06','After-tax savings','Contributions toward your future',fields(GROUPS.savings)+miniNote('Pre-tax retirement is already deducted above. These are contributions, not balances. Future net worth can reuse these savings with “Use Budget savings.”'))+
 `<details class="panel import-panel"><summary>Import a financial summary</summary><p>How summary imports work ${help('summaryImport')}</p><p>Use the CSV template to summarize your records. Review the changes before applying them. Your file stays in this browser.</p><div class="budget-actions"><button class="btn" id="download-summary-template">Download template</button><label class="btn" for="summary-file">Choose summary CSV</label><input id="summary-file" class="sr-only" type="file" accept=".csv,text/csv"></div><p class="inline-note">Bank statements must be summarized into these categories first. No bank connection is required.</p></details></div>`;
}

export function budgetChart(state,{money},ui){
 const b=budgetSummary(state.home,state.budget),a=budgetAllocation(b,ui.housing);
 const heading=`<div class="chart-heading"><h2>Where your money goes</h2><div class="segmented" role="group" aria-label="Budget chart style"><button id="budget-bars" data-budget-chart="bars" aria-pressed="${ui.chart==='bars'}">Bars</button><button id="budget-circle" data-budget-chart="circle" aria-pressed="${ui.chart==='circle'}">Circle</button></div></div><div class="segmented housing-switch" role="group" aria-label="Housing scenario"><button id="budget-current" data-budget-housing="current" aria-pressed="${ui.housing==='current'}">Current housing</button><button id="budget-proposed" data-budget-housing="proposed" aria-pressed="${ui.housing==='proposed'}">Proposed home</button></div>`;
 const caption=`<p class="chart-caption">Planned amounts per month, not tracked transactions. ${ui.housing==='proposed'?'Proposed ownership replaces current housing. Stress-test adjustments are not applied in Budget.':''}</p>`;
 if(ui.chart==='bars')return heading+`<div class="category-bars">${a.categories.map((c,i)=>`<button type="button" class="category-row" data-budget-category="${i}" aria-label="Edit ${c.name}, ${money(c.value)} per month"><span class="category-label"><span>${c.name} <span aria-hidden="true">↗</span></span><strong>${money(c.value)}</strong></span><span class="category-track" aria-hidden="true"><span class="allocation-${i}" style="width:${c.value/a.scale*100}%"></span></span></button>`).join('')}</div><p class="chart-caption">Select a category to edit it. Shared scale: ${money(a.scale)}. ${a.remaining>=0?money(a.remaining)+' remains unallocated.':money(-a.remaining)+' monthly shortfall.'}</p>`+caption;
 let offset=0;const stops=a.ring.map((c,i)=>{const start=offset;offset+=c.value/a.scale*100;return `var(--allocation-${i}) ${start}% ${offset}%`}).join(',');
 return heading+`<div class="allocation-circle-wrap"><div class="allocation-circle" role="img" aria-label="${a.ring.map(c=>c.name+': '+money(c.value)).join('; ')}" style="background:conic-gradient(${a.total===0&&a.remaining===0?'#e4ece7 0% 100%':stops})"><div><strong>${money(a.total)}</strong><span>planned / month</span></div></div></div><div class="allocation-legend">${a.ring.map((c,i)=>i<5?`<button type="button" class="category-label" data-budget-category="${i}" aria-label="Edit ${c.name}, ${money(c.value)} per month"><span><i class="legend-dot allocation-${i}" aria-hidden="true"></i>${c.name} ↗</span><strong>${money(c.value)}</strong></button>`:`<div class="category-label"><span><i class="legend-dot allocation-${i}" aria-hidden="true"></i>${c.name}</span><strong>${money(c.value)}</strong></div>`).join('')}</div>${a.remaining<0?'<p class="chart-caption">Circle shows planned allocations. The shortfall is shown separately.</p>':''}`+caption;
}

export function budgetResults(state,{money,row,lightRow},ui){
 const b=budgetSummary(state.home,state.budget),a=budgetAllocation(b,ui.housing),proposed=ui.housing==='proposed';
 return `<section class="result-card budget-result"><p class="eyebrow">${a.remaining<0?'MONTHLY SHORTFALL':'MONEY REMAINING / MONTH'}</p><div class="big-number ${a.remaining<0?'negative':''}">${money(Math.abs(a.remaining))}</div><p class="result-sub">${a.remaining<0?'Your plan allocates more than the income available.':'After the spending and savings entered.'}</p><div class="result-rule"></div>${row('Take-home before health premiums',money(b.takeHome))}${row('Total planned',money(a.total))}<p class="result-sub">Health premiums appear once in Essentials. Pre-tax retirement is already deducted from take-home.</p><details class="calculation-details"><summary>Follow the paycheck calculation</summary>${row('Gross income / month',money(b.gross))}${row('Less pre-tax retirement',money(b.retirement))}${row('Less modeled taxes',money(b.taxes))}</details></section><section class="panel budget-comparison"><h2>${proposed?'With the proposed home':'Your housing comparison'}</h2>${lightRow('Current housing / month',money(b.currentHousing))}${lightRow('Proposed ownership / month',money(b.proposedHousing))}${lightRow('Change in money remaining',money(b.proposedRemaining-b.currentRemaining))}<p class="inline-note">${proposed?'The chart includes proposed ownership instead of current housing.':'Switch to Proposed home to explore the change.'} Upfront cash is checked in the home calculators.</p><button class="btn" data-mode="backward">Adjust the home plan</button></section>`;
}
export function summaryTemplate(){return 'field,amount,period\r\n'+IMPORT_KEYS.map(key=>`${key},,${key==='householdGrossAnnual'?'annual':'monthly'}`).join('\r\n')+'\r\n'}
